use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Semaphore {
    count: Mutex<usize>,
    cv: Condvar,
}

impl Semaphore {
    fn new(count: usize) -> Self {
        Semaphore {
            count: Mutex::new(count),
            cv: Condvar::new(),
        }
    }

    fn acquire(&self, n: usize) {
        let mut c = self.count.lock().unwrap();
        while *c < n {
            c = self.cv.wait(c).unwrap();
        }
        *c -= n;
    }

    fn release(&self, n: usize) {
        let mut c = self.count.lock().unwrap();
        *c += n;
        self.cv.notify_all();
    }
}

fn w2(s: Arc<Semaphore>) {
    s.acquire(1);
    s.release(1);
}

fn w1(s: Arc<Semaphore>, out: Arc<Mutex<String>>) {
    let h1 = thread::spawn({
        let s = Arc::clone(&s);
        move || w2(s)
    });
    let h2 = thread::spawn({
        let s = Arc::clone(&s);
        move || w2(s)
    });
    h1.join().unwrap();
    h2.join().unwrap();
    let mut o = out.lock().unwrap();
    *o = String::from("DONE permits=1");
}

fn main() {
    let s = Arc::new(Semaphore::new(1));
    let out = Arc::new(Mutex::new(String::new()));

    let sup = thread::spawn({
        let s = Arc::clone(&s);
        let out = Arc::clone(&out);
        move || w1(s, out)
    });
    sup.join().unwrap();

    let o = out.lock().unwrap();
    println!("{}", *o);
}
